/* ── sort pricing so recommended is always in the middle ── */
if ($plans) {
    $featIdx = null;
    foreach ($plans as $i => $p) {
        if (!empty($p['recommended'])) { $featIdx = $i; break; }
    }
    if ($featIdx !== null) {
        $feat = $plans[$featIdx];
        unset($plans[$featIdx]);
        $plans = array_values($plans);
        array_splice($plans, (int) floor(count($plans) / 2), 0, [$feat]);
    }
}

